md=['# Operad skills audit — in progress','',f"Source commit `{r['source_commit']}`. **{r['full_source_read_count']}/{r['scope_count']} full bodies reviewed; {len(r['remaining_work'])} pending.** Exact hashes and per-file semantic dispositions are in JSON. Mechanical scans alone receive no full-read credit.",'',f"{len(r['claims'])} synthesis claims; {len(r['findings'])} actionable findings; 42 observed independent bounded controls and one unavailable shell control. No retained skill, provider or native build executed.",'','Useful reusable components include finite fibre-factorization witnesses, a correct fixed triangle primal-dual example, problem/custody binding, explicit unavailable states, and learning-evidence boundaries.','','Material defects include impossible gauge-CUT descent (F057), incorrect arbitrary-projector distance (F045), wrong LP witness bounds (F031/F060), unsafe repair modes and weak gates (F019–F028), and semantic verification labels attached to existence/substring checks (F049/F062/F064).','','All historical claims remain separate from fresh evidence; original source bytes are preserved. This is an incomplete scoped audit, with explicit remaining work in JSON.']
(H/(P+'.md')).write_text('\n'.join(md)+'\n');print(json.dumps({'full':r['full_source_read_count'],'findings':len(r['findings'])}))
